// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    Log l;

    function setUp() public { l = new Log(); c = new W_WALLET(address(l)); }

    function testFuzz_property(uint256 amount, address actor, uint256 t) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        vm.warp(bound(t, 1, 2e9));
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(t);

        // A completed Put must have appended at least one entry to the Log:
        // the first History entry must now be readable (i.e. History is non-empty).
        bool logged;
        try l.History(0) {
            logged = true;
        } catch {
            logged = false;
        }
        assertTrue(logged);
    }
}
